import { validationFailed } from './errors.js';

export const MINUTE_IN_MS = 60_000;
export const DAY_IN_MS = 86_400_000;

/** A half-open range `[startsAt, endsAt)`: a range that ends exactly when another starts does not overlap it. */
export interface Interval {
  startsAt: Date;
  endsAt: Date;
}

export function parseInstant(value: string): Date {
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) {
    throw validationFailed('Value is not a valid instant', { value });
  }
  return parsed;
}

export function durationMinutes(start: Date, end: Date): number {
  return Math.round((end.getTime() - start.getTime()) / MINUTE_IN_MS);
}

export function isBefore(a: Date, b: Date): boolean {
  return a.getTime() < b.getTime();
}

export function addMinutes(instant: Date, minutes: number): Date {
  return new Date(instant.getTime() + minutes * MINUTE_IN_MS);
}

export function addDays(instant: Date, days: number): Date {
  return new Date(instant.getTime() + days * DAY_IN_MS);
}

export function earliest(a: Date, b: Date): Date {
  return isBefore(a, b) ? a : b;
}

export function latest(a: Date, b: Date): Date {
  return isBefore(a, b) ? b : a;
}

export function overlaps(a: Interval, b: Interval): boolean {
  return isBefore(a.startsAt, b.endsAt) && isBefore(b.startsAt, a.endsAt);
}

/** Builds an interval, rejecting empty and inverted ranges. */
export function toInterval(startsAt: Date, endsAt: Date): Interval {
  if (!isBefore(startsAt, endsAt)) {
    throw validationFailed('endsAt must be after startsAt', {
      startsAt: startsAt.toISOString(),
      endsAt: endsAt.toISOString(),
    });
  }
  return { startsAt, endsAt };
}

export function parseInterval(startsAt: string, endsAt: string): Interval {
  return toInterval(parseInstant(startsAt), parseInstant(endsAt));
}
