      failures.push({
        index: candidate.index,
        code: 'BOOKING_CONFLICT',
        message: 'Overlaps another booking in the same request',
        details: { conflictsWithIndex: clash.index, requested: toIso(candidate.interval) },
      });
      continue;
    }
    accepted.push(candidate);
  }

  if (failures.length > 0) {
    throw batchRejected(failures);
  }

  return repository.runInTransaction(async (tx) => {
    for (const { index, item, interval } of accepted) {
      const conflict = await repository.findOverlapping(item.roomId, interval, {}, tx);
      if (conflict) {
        failures.push({
          index,
          code: 'BOOKING_CONFLICT',
          message: 'Room is already booked for this period',
          details: {
            conflictingBookingId: conflict.id,
            requested: toIso(interval),
            suggestions: await suggestAlternatives(item.roomId, interval, tx),
          },
        });
      }
    }
    if (failures.length > 0) {
      throw batchRejected(failures);
    }

    const created: Booking[] = [];
    for (const { item, interval } of accepted) {
      created.push(
        await repository.create(
          { roomId: item.roomId, userId: item.userId, title: item.title, ...interval },
          tx,
        ),
      );
    }
    return created;
  });
}

/** Lists the stretches of `[from, to)` in which the room is free. */
export async function getRoomAvailability(
  roomId: string,
  query: AvailabilityInput,
): Promise<Availability> {
  const window = parseInterval(query.from, query.to);
  if (window.endsAt.getTime() - window.startsAt.getTime() > MAX_AVAILABILITY_WINDOW_DAYS * DAY_IN_MS) {
    throw validationFailed(
      `The window between from and to must not exceed ${MAX_AVAILABILITY_WINDOW_DAYS} days`,
      { maxWindowDays: MAX_AVAILABILITY_WINDOW_DAYS },
    );
  }

  const rooms = await repository.findExistingRoomIds([roomId]);
  if (!rooms.has(roomId)) {
    throw notFound('Room');
  }

  const busy = await repository.listBusyIntervals(roomId, window);
  const limit = normalizeLimit(query.limit);

  return {
    roomId,
    from: window.startsAt,
    to: window.endsAt,
    durationMinutes: query.durationMinutes ?? null,
    slots: freeSlots(busy, window, (query.durationMinutes ?? 0) * MINUTE_IN_MS).slice(0, limit),
  };
}

export async function getBooking(id: string): Promise<Booking> {
  const booking = await repository.findById(id);
  if (!booking) {
    throw notFound('Booking');
  }
  return booking;
}

export async function listBookings(query: ListBookingsInput): Promise<Page<Booking>> {
  const limit = normalizeLimit(query.limit);
  const offset = normalizeOffset(query.offset);
  const [data, total] = await repository.list({
    roomId: query.roomId,
    userId: query.userId,
    status: query.status,
    from: query.from ? parseInstant(query.from) : undefined,
    to: query.to ? parseInstant(query.to) : undefined,
    limit,
    offset,
  });
  return paginated(data, total, limit, offset);
}

export async function updateBooking(id: string, input: UpdateBookingInput): Promise<Booking> {
  const current = await getBooking(id);
  const roomId = input.roomId ?? current.roomId;
  const userId = input.userId ?? current.userId;
  const startsAt = input.startsAt !== undefined ? parseInstant(input.startsAt) : current.startsAt;
  const endsAt = input.endsAt !== undefined ? parseInstant(input.endsAt) : current.endsAt;

  // Only validate the range when the caller touches it: an edit to the title
  // alone should not start failing on a row stored before the rule existed.
  const movedInTime = input.startsAt !== undefined || input.endsAt !== undefined;
  const interval = movedInTime ? toInterval(startsAt, endsAt) : { startsAt, endsAt };

  if (input.roomId !== undefined || input.userId !== undefined) {
    const known = await loadKnownReferences([{ roomId, userId }]);
    const missing = missingReference({ roomId, userId }, known);
    if (missing) {
      throw notFound(missing);
    }
  }

  return repository.runInTransaction(async (tx) => {
    // A cancelled booking holds no slot, so moving it can never clash.
    if (current.status === BOOKING_ACTIVE && (movedInTime || input.roomId !== undefined)) {
      const conflict = await repository.findOverlapping(roomId, interval, { excludeId: id }, tx);
      if (conflict) {
        throw await conflictFor(roomId, interval, conflict, tx);
      }
    }
    return repository.update(
      id,
      {
        ...(input.roomId !== undefined ? { roomId } : {}),
        ...(input.userId !== undefined ? { userId } : {}),
        ...(input.title !== undefined ? { title: input.title } : {}),
        ...(input.startsAt !== undefined ? { startsAt: interval.startsAt } : {}),
        ...(input.endsAt !== undefined ? { endsAt: interval.endsAt } : {}),
      },
      tx,
    );
  });
}

export async function cancelBooking(id: string): Promise<Booking> {
  const booking = await getBooking(id);
  if (booking.status === BOOKING_CANCELLED) {
    return booking;
  }
  return repository.updateStatus(id, BOOKING_CANCELLED);
}

export async function deleteBooking(id: string): Promise<void> {
  await getBooking(id);
  await repository.remove(id);
}

/**
 * Turns a clash into an error that names the offending booking and proposes the
 * next free slots of the same length, so the caller does not have to guess again.
 */
async function conflictFor(
  roomId: string,
  interval: Interval,
  conflict: Booking,
  db: repository.Db,
): Promise<AppError> {
  return bookingConflict(conflict.id, {
    requested: toIso(interval),
    conflictingBooking: {
      id: conflict.id,
      ...toIso({ startsAt: conflict.startsAt, endsAt: conflict.endsAt }),
    },
    suggestions: await suggestAlternatives(roomId, interval, db),
  });
}

async function suggestAlternatives(
  roomId: string,
  interval: Interval,
  db: repository.Db,
): Promise<IsoInterval[]> {
  const durationMs = interval.endsAt.getTime() - interval.startsAt.getTime();
  // Search the requested duration plus a week of slack, so even a long booking
  // has room to land somewhere inside the window.
  const window: Interval = {
    startsAt: interval.startsAt,
    endsAt: new Date(interval.startsAt.getTime() + durationMs + SUGGESTION_LOOKAHEAD_DAYS * DAY_IN_MS),
  };
  const busy = await repository.listBusyIntervals(roomId, window, db);
  return suggestSlots(busy, window, durationMs, MAX_SUGGESTIONS).map(toIso);
}

async function loadKnownReferences(
  items: { roomId: string; userId: string }[],
): Promise<KnownReferences> {
  const [rooms, users] = await Promise.all([
    repository.findExistingRoomIds([...new Set(items.map((item) => item.roomId))]),
    repository.findExistingUserIds([...new Set(items.map((item) => item.userId))]),
  ]);
  return { rooms, users };
}

function missingReference(
  item: { roomId: string; userId: string },
  known: KnownReferences,
): 'Room' | 'User' | null {
  if (!known.rooms.has(item.roomId)) return 'Room';
  if (!known.users.has(item.userId)) return 'User';
  return null;
}

function batchRejected(failures: BatchFailure[]): AppError {
  const ordered = [...failures].sort((a, b) => a.index - b.index);
  const message = 'No booking was created because some entries were rejected';
  return failures.some((failure) => failure.code === 'BOOKING_CONFLICT')
    ? new AppError('BOOKING_CONFLICT', 409, message, { failures: ordered })
    : new AppError('VALIDATION_ERROR', 400, message, { failures: ordered });
}

function asFailure(index: number, error: unknown): BatchFailure {
  if (!(error instanceof AppError)) throw error;
  return { index, code: error.code, message: error.message, details: error.details };
}

function toIso(interval: Interval): IsoInterval {
  return {
    startsAt: interval.startsAt.toISOString(),
    endsAt: interval.endsAt.toISOString(),
  };
}
