import type { Booking, Prisma } from '@prisma/client';
import { prisma } from '../../db/client.js';
import type { Interval } from '../../shared/time.js';
import { BOOKING_ACTIVE } from './schema.js';

/** Either the shared client or the handle given inside `runInTransaction`. */
export type Db = Prisma.TransactionClient;

export interface BookingData {
  roomId: string;
  userId: string;
  title: string;
  startsAt: Date;
  endsAt: Date;
}

export interface BookingFilter {
  roomId?: string;
  userId?: string;
  status?: string;
  from?: Date;
  to?: Date;
  limit: number;
  offset: number;
}

export interface BusyInterval extends Interval {
  id: string;
}

export function runInTransaction<T>(fn: (tx: Db) => Promise<T>): Promise<T> {
  return prisma.$transaction(fn);
}

export function create(data: BookingData, db: Db = prisma): Promise<Booking> {
  return db.booking.create({ data });
}

/**
 * Finds an active booking of the same room whose time overlaps `interval`.
 * Overlap is half-open, so back-to-back bookings do not collide.
 */
export function findOverlapping(
  roomId: string,
  interval: Interval,
  options: { excludeId?: string } = {},
  db: Db = prisma,
): Promise<Booking | null> {
  return db.booking.findFirst({
    where: {
      roomId,
      status: BOOKING_ACTIVE,
      startsAt: { lt: interval.endsAt },
      endsAt: { gt: interval.startsAt },
      ...(options.excludeId ? { id: { not: options.excludeId } } : {}),
    },
    orderBy: { startsAt: 'asc' },
  });
}

/** Lists the active bookings of a room that occupy any part of `window`. */
export function listBusyIntervals(
  roomId: string,
  window: Interval,
  db: Db = prisma,
): Promise<BusyInterval[]> {
  return db.booking.findMany({
    where: {
      roomId,
      status: BOOKING_ACTIVE,
      startsAt: { lt: window.endsAt },
      endsAt: { gt: window.startsAt },
    },
    orderBy: { startsAt: 'asc' },
    select: { id: true, startsAt: true, endsAt: true },
  });
}

export async function findExistingRoomIds(ids: string[]): Promise<Set<string>> {
  const rooms = await prisma.room.findMany({ where: { id: { in: ids } }, select: { id: true } });
  return new Set(rooms.map((room) => room.id));
}

export async function findExistingUserIds(ids: string[]): Promise<Set<string>> {
  const users = await prisma.user.findMany({ where: { id: { in: ids } }, select: { id: true } });
  return new Set(users.map((user) => user.id));
}

export function findById(id: string): Promise<Booking | null> {
  return prisma.booking.findUnique({ where: { id } });
}

export function list(filter: BookingFilter): Promise<[Booking[], number]> {
  const where: Prisma.BookingWhereInput = {};
  if (filter.roomId) where.roomId = filter.roomId;
  if (filter.userId) where.userId = filter.userId;
  if (filter.status) where.status = filter.status;
  if (filter.from) where.startsAt = { gte: filter.from };
  if (filter.to) where.endsAt = { lte: filter.to };

  return prisma.$transaction([
    prisma.booking.findMany({
      where,
      take: filter.limit,
      skip: filter.offset,
      orderBy: { startsAt: 'asc' },
    }),
    prisma.booking.count({ where }),
  ]);
}

export function update(id: string, data: Partial<BookingData>): Promise<Booking> {
  return prisma.booking.update({ where: { id }, data });
}

export function updateStatus(id: string, status: string): Promise<Booking> {
  return prisma.booking.update({ where: { id }, data: { status } });
}

export function remove(id: string): Promise<Booking> {
  return prisma.booking.delete({ where: { id } });
}

