  it('rejects a booking identical to an active one', async () => {
    await book(24, 25);
    expect((await book(24, 25, 'Same')).statusCode).toBe(409);
  });

  it('accepts a booking that ends exactly when another starts', async () => {
    await book(24, 25);
    expect((await book(23, 24, 'Before')).statusCode).toBe(201);
  });

  it('describes the booking it collided with', async () => {
    const first = await book(24, 25);
    const details = (await book(24.5, 25.5, 'Overlap')).json().error.details;
    expect(details.conflictingBooking).toEqual({
      id: first.json().id,
      startsAt: inHours(24),
      endsAt: inHours(25),
    });
    expect(details.requested).toEqual({ startsAt: inHours(24.5), endsAt: inHours(25.5) });
  });

  it('suggests free slots of the requested length when it rejects a booking', async () => {
    await book(24, 25);
    const suggestions = (await book(24, 25, 'Clash')).json().error.details.suggestions;
    expect(suggestions).toEqual([{ startsAt: inHours(25), endsAt: inHours(26) }]);
  });

  it('skips over every booking in the way when suggesting', async () => {
    await book(24, 25);
    await book(25, 26, 'Next');
    const suggestions = (await book(24, 25, 'Clash')).json().error.details.suggestions;
    expect(suggestions[0]).toEqual({ startsAt: inHours(26), endsAt: inHours(27) });
  });

  it('proposes a slot that can actually be booked', async () => {
    await book(24, 25);
    const suggestion = (await book(24, 25, 'Clash')).json().error.details.suggestions[0];
    const retry = await app.inject({
      method: 'POST',
      url: '/bookings',
      payload: { roomId, userId, title: 'Retry', ...suggestion },
    });
    expect(retry.statusCode).toBe(201);
  });

  it('rejects a booking that ends before it starts', async () => {
    const response = await book(25, 24, 'Backwards');
    expect(response.statusCode).toBe(400);
    expect(response.json().error.code).toBe('VALIDATION_ERROR');
  });

  it('rejects a booking with no duration', async () => {
    expect((await book(24, 24, 'Instant')).statusCode).toBe(400);
  });

  it('answers 404 for a room that does not exist', async () => {
    const response = await app.inject({
      method: 'POST',
      url: '/bookings',
      payload: { roomId: 'missing', userId, title: 'Sync', startsAt: inHours(24), endsAt: inHours(25) },
    });
    expect(response.statusCode).toBe(404);
    expect(response.json().error.message).toBe('Room not found');
  });

