    const response = await app.inject({
      method: 'POST',
      url: '/bookings',
      payload: { roomId, userId: 'missing', title: 'Sync', startsAt: inHours(24), endsAt: inHours(25) },
    });
    expect(response.statusCode).toBe(404);
    expect(response.json().error.message).toBe('User not found');
  });

  it('rejects an update that moves a booking onto an occupied slot', async () => {
    const first = await book(24, 25);
    const second = await book(30, 31, 'Second');
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${second.json().id}`,
      payload: { startsAt: inHours(24.5), endsAt: inHours(25.5) },
    });
    expect(response.statusCode).toBe(409);
    expect(response.json().error.details.conflictingBookingId).toBe(first.json().id);
    expect(response.json().error.details.suggestions).toBeDefined();
  });

  it('leaves the booking untouched when an update is rejected', async () => {
    await book(24, 25);
    const second = await book(30, 31, 'Second');
    await app.inject({
      method: 'PATCH',
      url: `/bookings/${second.json().id}`,
      payload: { startsAt: inHours(24.5), endsAt: inHours(25.5) },
    });
    const reread = await app.inject({ method: 'GET', url: `/bookings/${second.json().id}` });
    expect(reread.json().startsAt).toBe(inHours(30));
  });

  it('does not treat a booking as a conflict with itself', async () => {
    const created = await book(24, 25);
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${created.json().id}`,
      payload: { startsAt: inHours(24), endsAt: inHours(25), title: 'Renamed' },
    });
    expect(response.statusCode).toBe(200);
    expect(response.json().title).toBe('Renamed');
  });

