import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'vitest';
import type { FastifyInstance } from 'fastify';
import { createTestApp, resetDb } from './helpers/app.js';

const HOUR = 3_600_000;

interface Entry {
  roomId: string;
  userId: string;
  title: string;
  startsAt: string;
  endsAt: string;
}

describe('POST /bookings/batch', () => {
  let app: FastifyInstance;
  let roomId: string;
  let otherRoomId: string;
  let userId: string;
  let base: number;

  beforeAll(async () => {
    app = await createTestApp();
  });

  afterAll(async () => {
    await app.close();
  });

  beforeEach(async () => {
    base = Date.now();
    await resetDb();
    const room = await app.inject({
      method: 'POST',
      url: '/rooms',
      payload: { name: 'Aurora', capacity: 6 },
    });
    roomId = room.json().id;
    const other = await app.inject({
      method: 'POST',
      url: '/rooms',
      payload: { name: 'Borealis', capacity: 4 },
    });
    otherRoomId = other.json().id;
    const user = await app.inject({
      method: 'POST',
      url: '/users',
      payload: { name: 'Ada Lovelace', email: 'ada@example.com' },
    });
    userId = user.json().id;
  });

  function inHours(hours: number): string {
    return new Date(base + hours * HOUR).toISOString();
  }

  function entry(startHours: number, endHours: number, title: string, room = roomId): Entry {
    return { roomId: room, userId, title, startsAt: inHours(startHours), endsAt: inHours(endHours) };
  }

  function batch(bookings: Entry[]) {
    return app.inject({ method: 'POST', url: '/bookings/batch', payload: { bookings } });
  }

  async function storedBookings(): Promise<number> {
    const response = await app.inject({ method: 'GET', url: '/bookings' });
    return response.json().pagination.total;
  }

  it('creates every booking of the request', async () => {
    const response = await batch([entry(24, 25, 'A'), entry(26, 27, 'B'), entry(28, 29, 'C')]);
    expect(response.statusCode).toBe(201);
    expect(response.json().data).toHaveLength(3);
    expect(response.json().data.map((booking: { title: string }) => booking.title)).toEqual([
      'A',
      'B',
      'C',
    ]);
  });

  it('persists everything it reports as created', async () => {
    await batch([entry(24, 25, 'A'), entry(26, 27, 'B')]);
    expect(await storedBookings()).toBe(2);
  });

  it('accepts back to back bookings in the same request', async () => {
    const response = await batch([entry(24, 25, 'A'), entry(25, 26, 'B')]);
    expect(response.statusCode).toBe(201);
  });

  it('accepts overlapping bookings when the rooms differ', async () => {
    const response = await batch([entry(24, 25, 'A'), entry(24, 25, 'B', otherRoomId)]);
    expect(response.statusCode).toBe(201);
  });

  it('rejects the request when an entry clashes with a stored booking', async () => {
    await batch([entry(24, 25, 'Existing')]);
    const response = await batch([entry(30, 31, 'Fine'), entry(24.5, 25.5, 'Clash')]);
    expect(response.statusCode).toBe(409);
    expect(response.json().error.code).toBe('BOOKING_CONFLICT');
  });

  it('creates nothing at all when one entry is rejected', async () => {
    await batch([entry(24, 25, 'Existing')]);
    await batch([entry(30, 31, 'Fine'), entry(24.5, 25.5, 'Clash')]);
    expect(await storedBookings()).toBe(1);
  });

  it('reports the position of the rejected entry', async () => {
    await batch([entry(24, 25, 'Existing')]);
    const failures = (await batch([entry(30, 31, 'Fine'), entry(24.5, 25.5, 'Clash')])).json().error
      .details.failures;
    expect(failures).toHaveLength(1);
    expect(failures[0].index).toBe(1);
    expect(failures[0].code).toBe('BOOKING_CONFLICT');
  });

  it('suggests alternatives for an entry that clashes', async () => {
    await batch([entry(24, 25, 'Existing')]);
    const failures = (await batch([entry(24, 25, 'Clash')])).json().error.details.failures;
    expect(failures[0].details.suggestions).toEqual([
      { startsAt: inHours(25), endsAt: inHours(26) },
    ]);
  });

  it('rejects two entries of the same request that overlap each other', async () => {
    const response = await batch([entry(24, 26, 'A'), entry(25, 27, 'B')]);
    expect(response.statusCode).toBe(409);
    const failures = response.json().error.details.failures;
    expect(failures).toHaveLength(1);
    expect(failures[0].index).toBe(1);
    expect(failures[0].details.conflictsWithIndex).toBe(0);
    expect(await storedBookings()).toBe(0);
  });

  it('reports every problem of the request in one response', async () => {
    const response = await batch([
      entry(25, 24, 'Backwards'),
      entry(24, 25, 'Fine'),
      { ...entry(30, 31, 'Unknown room'), roomId: 'missing' },
      entry(24.5, 25.5, 'Overlaps entry 1'),
    ]);
    const failures = response.json().error.details.failures;
    expect(failures.map((failure: { index: number }) => failure.index)).toEqual([0, 2, 3]);
    expect(failures.map((failure: { code: string }) => failure.code)).toEqual([
      'VALIDATION_ERROR',
      'NOT_FOUND',
      'BOOKING_CONFLICT',
    ]);
  });

  it('answers 400 when nothing clashed but entries were invalid', async () => {
    const response = await batch([
      entry(24, 25, 'Fine'),
      { ...entry(30, 31, 'Unknown user'), userId: 'missing' },
    ]);
    expect(response.statusCode).toBe(400);
    expect(response.json().error.code).toBe('VALIDATION_ERROR');
    expect(response.json().error.details.failures[0]).toMatchObject({
      index: 1,
      code: 'NOT_FOUND',
      message: 'User not found',
    });
  });

  it('rejects an entry whose instants cannot be parsed', async () => {
    const response = await batch([{ ...entry(24, 25, 'Bad'), startsAt: 'yesterday' }]);
    expect(response.statusCode).toBe(400);
    expect(response.json().error.details.failures[0].code).toBe('VALIDATION_ERROR');
  });

  it('rejects an empty request', async () => {
    const response = await batch([]);
    expect(response.statusCode).toBe(400);
  });

  it('rejects a request larger than the supported batch size', async () => {
    const bookings = Array.from({ length: 26 }, (_, index) =>
      entry(24 + index * 2, 25 + index * 2, `Meeting ${index}`),
    );
    const response = await batch(bookings);
    expect(response.statusCode).toBe(400);
  });

  it('fills a day of meetings in a single call', async () => {
    const bookings = Array.from({ length: 8 }, (_, index) =>
      entry(24 + index, 24.5 + index, `Slot ${index}`),
    );
    expect((await batch(bookings)).statusCode).toBe(201);
    expect(await storedBookings()).toBe(8);
  });
});
